/**
 * The hire wizard's write (ADR-0051 decision 3). Install creates an
 * agent of origin `installed` whose definition is read-only and pinned
 * to the version by id and digest. Fork creates an editable agent that
 * records `origin_listing_id`, `origin_version_id` and `origin_digest`.
 * A skill is added as a project skill, pinned the same way.
 *
 * Every required toolkit or MCP type needs a binding to a project
 * toolkit, or `disabled`. Above low tier, or with write tools, the agent
 * is created with its tools disabled and a change request of kind
 * `hire` enables them on approval. A personal project has no second
 * approver: the call answers 409 `hire_needs_shared_project` unless the
 * platform policy `marketplace_personal_self_approve` is on, in which
 * case the hire is self-approved and audited
 * (internal/api/v2/eliteacore/marketplace_hire.go).
 * @summary Hire a listing into the project (Install or Fork)
 */
export const hireMarketplaceListing = async (
  projectId: string,
  marketplaceHireRequest: MarketplaceHireRequest,
  options?: Parameters<typeof eliteaFetch>[1],
): Promise<hireMarketplaceListingResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return eliteaFetch<hireMarketplaceListingResponse>(
    getHireMarketplaceListingUrl(projectId),
    {
      ...options,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(marketplaceHireRequest),
    },
  );
};

